function body(text) {
  return new Paragraph({
    alignment: AlignmentType.JUSTIFIED,
    indent: { firstLine: 480 },
    spacing: { line: 312, after: 80 },
    children: [new TextRun({ text, size: 24, color: "000000", font: { ascii: "Carlito", eastAsia: "Microsoft YaHei" } })],
  });
}

function bodyBold(boldText, normalText) {
  return new Paragraph({
    alignment: AlignmentType.JUSTIFIED,
    indent: { firstLine: 480 },
    spacing: { line: 312, after: 80 },
    children: [
      new TextRun({ text: boldText, bold: true, size: 24, color: "000000", font: { ascii: "Carlito", eastAsia: "Microsoft YaHei" } }),
      new TextRun({ text: normalText, size: 24, color: "000000", font: { ascii: "Carlito", eastAsia: "Microsoft YaHei" } }),
    ],
  });
}

function bodyNoIndent(text) {
  return new Paragraph({
    alignment: AlignmentType.JUSTIFIED,
    spacing: { line: 312, after: 80 },
    children: [new TextRun({ text, size: 24, color: "000000", font: { ascii: "Carlito", eastAsia: "Microsoft YaHei" } })],
  });
}

function spacer(before = 100) {
  return new Paragraph({ spacing: { before }, children: [] });
}

// Table helper
function makeTable(headers, rows, colWidths) {
  const hdrRow = new TableRow({
    tableHeader: true,
    cantSplit: true,
    children: headers.map((h, i) =>
      new TableCell({
        width: { size: colWidths[i], type: WidthType.PERCENTAGE },
        shading: { type: ShadingType.CLEAR, fill: P.table.headerBg },
        margins: { top: 60, bottom: 60, left: 100, right: 100 },
        children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: h, bold: true, size: 21, color: P.table.headerText, font: { ascii: "Carlito", eastAsia: "Microsoft YaHei" } })] })],
      })
    ),
  });

  const dataRows = rows.map((row, ri) =>
    new TableRow({
      cantSplit: true,
      children: row.map((cell, ci) =>
        new TableCell({
          width: { size: colWidths[ci], type: WidthType.PERCENTAGE },
          shading: { type: ShadingType.CLEAR, fill: ri % 2 === 0 ? P.table.surface : "FFFFFF" },
          margins: { top: 50, bottom: 50, left: 100, right: 100 },
          children: [new Paragraph({ alignment: AlignmentType.LEFT, children: [new TextRun({ text: String(cell), size: 21, color: "000000", font: { ascii: "Carlito", eastAsia: "Microsoft YaHei" } })] })],
        })
      ),
    })
  );

  return new Table({
    width: { size: 100, type: WidthType.PERCENTAGE },
    borders: {
      top: { style: BorderStyle.SINGLE, size: 2, color: P.table.accentLine },
      bottom: { style: BorderStyle.SINGLE, size: 2, color: P.table.accentLine },
      left: { style: BorderStyle.NONE },
      right: { style: BorderStyle.NONE },
      insideHorizontal: { style: BorderStyle.SINGLE, size: 1, color: P.table.innerLine },
      insideVertical: { style: BorderStyle.NONE },
    },
    rows: [hdrRow, ...dataRows],
  });
}

function tableCaption(text) {
  return new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 80, after: 200, line: 312 },
    children: [new TextRun({ text, italics: true, size: 20, color: P.secondary, font: { ascii: "Carlito", eastAsia: "Microsoft YaHei" } })],
  });
}

